contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single public test entry. We take a deposit amount and a receiver address.
    // We require the amount > 0 and receiver != address(0) per depositUsdc preconditions.
    function run(uint256 amount, address receiver) public payable {
        require(amount > 0 && receiver != address(0));

        // Read observables before the call
        uint256 beforeRound = c.currentRound();
        uint256 beforeRoundUsdc = c.roundUsdcBalance();
        // user's usdcBalance before
        uint256 beforeUserUsdc = c.usdcBalance(receiver);
        uint256 beforeUnclaimed = c.unclaimedShares(receiver);

        // We cannot actually transfer USDC token in this test environment; depositUsdc calls usdc.transferFrom.
        // The contract will likely revert unless msg.sender (this contract) has allowance and balance.
        // We therefore call depositUsdc and catch whether it reverts.
        bool reverted;
        try c.depositUsdc(amount, receiver) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after the call
        uint256 afterRound = c.currentRound();
        uint256 afterRoundUsdc = c.roundUsdcBalance();
        uint256 afterUserUsdc = c.usdcBalance(receiver);
        uint256 afterUnclaimed = c.unclaimedShares(receiver);

        // General rule (single assert): If depositUsdc did NOT revert then
        // - currentRound must be unchanged
        // - roundUsdcBalance must increase by exactly amount
        // - the user's usdcBalance must increase by exactly amount (so afterUserUsdc == beforeUserUsdc + amount)
        // - unclaimedShares must be >= beforeUnclaimed (non-decreasing)
        // If it reverted then none of the observed balances in c should have increased as a result of this call
        // (we express that as: either not reverted and the expected increases hold, OR reverted and after values equal before values).

        assert(
            (!reverted &&
                afterRound == beforeRound &&
                afterRoundUsdc == beforeRoundUsdc + amount &&
                afterUserUsdc == beforeUserUsdc + amount &&
                afterUnclaimed >= beforeUnclaimed
            ) || (
                reverted &&
                afterRound == beforeRound &&
                afterRoundUsdc == beforeRoundUsdc &&
                afterUserUsdc == beforeUserUsdc &&
                afterUnclaimed == beforeUnclaimed
            )
        );
    }

    receive() external payable {}
}

