    // params: receiver and amount to claim
    function run(address receiver, uint256 amount) public payable {
        // Observe pre-state via public getters
        uint256 beforeUnclaimed = c.unclaimedShares(address(this));
        uint256 beforeVaultBalance = c.dnGmxJuniorVault().balanceOf(address(this));

        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.unclaimedShares(address(this));
        uint256 afterVaultBalance = c.dnGmxJuniorVault().balanceOf(address(this));

        // General rule:
        // - If receiver is the zero address the call must revert.
        // - Otherwise, if the call did not revert then the caller's unclaimedShares cannot have increased
        //   and the caller's vault token balance cannot have decreased as a result of claim.
        assert(
            (receiver == address(0) && reverted) ||
            (receiver != address(0) && (
                (!reverted && afterUnclaimed <= beforeUnclaimed && afterVaultBalance >= beforeVaultBalance) ||
                (reverted && afterUnclaimed == beforeUnclaimed && afterVaultBalance == beforeVaultBalance)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: receiver and amount to claim
    function run(address receiver, uint256 amount) public payable {
        // observe pre-state via public getters (only allowed public/external interactions)
        uint256 beforeUnclaimed = c.unclaimedShares(address(this));
        uint256 beforeReceiverVault = c.dnGmxJuniorVault().balanceOf(receiver);
        uint256 beforeCallerVault = c.dnGmxJuniorVault().balanceOf(address(this));

        bool reverted;
        // perform the state-changing call as a top-level try/catch
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterUnclaimed = c.unclaimedShares(address(this));
        uint256 afterReceiverVault = c.dnGmxJuniorVault().balanceOf(receiver);
        uint256 afterCallerVault = c.dnGmxJuniorVault().balanceOf(address(this));

        // General rule asserted:
        // - If receiver == address(0) the call must revert.
        // - Otherwise, if the call succeeded it must reduce caller's unclaimedShares by exactly `amount`
        //   and increase receiver's vault token balance by exactly `amount` (caller vault balance unchanged by claim itself
        //   because tokens are transferred from caller to receiver via dnGmxJuniorVault.transfer).
        assert(
            (receiver == address(0) && reverted) ||
            (receiver != address(0) && (
                (!reverted && afterUnclaimed + amount == beforeUnclaimed && afterReceiverVault == beforeReceiverVault + amount && afterCallerVault == beforeCallerVault) ||
                (reverted && afterUnclaimed == beforeUnclaimed && afterReceiverVault == beforeReceiverVault && afterCallerVault == beforeCallerVault)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: amount and receiver
    function run(uint256 amount, address receiver) public payable {
        // Precondition: receiver must be non-zero (depositUsdc reverts if zero) and amount > 0 to exercise main path
        require(receiver != address(0));
        require(amount > 0);

        // ensure this contract has approved/has USDC to transferFrom in real world this would need ERC20 setup.
        // For property test we only interact with c's external view/state and call depositUsdc which may revert.

        // Read before values
        uint256 beforeRoundUsdc = c.roundUsdcBalance();
        uint256 beforeUserUsdc = c.usdcBalance(receiver);

        // Make the call and record whether it reverted
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterRoundUsdc = c.roundUsdcBalance();
        uint256 afterUserUsdc = c.usdcBalance(receiver);

        // General rule:
        // If depositUsdc succeeded (did not revert), then afterRoundUsdc >= beforeRoundUsdc and
        // afterUserUsdc >= beforeUserUsdc, and the increment to roundUsdcBalance is at least amount
        // OR if it reverted then state did not increase (we allow reverts).
        assert(
            reverted
            || (afterRoundUsdc >= beforeRoundUsdc && afterUserUsdc >= beforeUserUsdc && afterRoundUsdc - beforeRoundUsdc >= amount)
        );
    }

    receive() external payable {}
}
